def do_block_forward(
    self,
    layer_idx,
    samples,
    hook_name=None,
    use_quant_block=False,
    enable_quant=False,
):
    act_stat = {}
    outs, hooks = [], []
    block = self._build_block_for_forward(
        layer_idx, use_quant_block=use_quant_block
    )
    if use_quant_block:
        import amct_pytorch.common.models.llm.common.quant_apply as quant_apply

        quant_apply.set_model_to_observe(block, not enable_quant)

    block = self._dispatch_block(block).eval()
    if use_quant_block and hook_name is None:
        for mod in block.modules():
            if isinstance(mod, QuantLinear):
                mod.eval_mode = True
                mod.cached_eval_weight = None
    if hook_name is not None:
        register_forward_hooks(block, hook_name, hooks, act_stat)

    block_kwargs = self.get_block_forward_kwargs()
    input_ids_list = (
        self.input_ids if self.input_ids is not None else [None] * len(samples)
    )
    with torch.no_grad():
        for sample, ids in zip(samples, input_ids_list):
            sample = sample.to(self.args.device)
            call_kwargs = dict(block_kwargs)
            if ids is not None:
                call_kwargs["input_ids"] = ids.to(self.args.device)
            out = block(sample, **call_kwargs)
            out = out[0] if isinstance(out, (tuple, list)) else out
            outs.append(out.to("cpu"))

    if hook_name is not None:
        for hook in hooks:
            hook.remove()
        self.save_block_hook_inputs(act_stat, hook_name, layer_idx)
    try:
        from accelerate.hooks import remove_hook_from_module

        remove_hook_from_module(block, recurse=True)
    except Exception:
        pass
    block = None
    gc.collect()
    torch.npu.empty_cache()
    return outs

